// func StackAccum(x uint64, n uint64) uint64
TEXT ·StackAccum(SB), NOSPLIT, $16-24
	MOVQ x+0(FP), AX
	MOVQ n+8(FP), CX
	XORQ DX, DX
	MOVQ DX, (SP)
	MOVQ CX, 8(SP)

accum_loop:
	MOVQ  8(SP), CX
	TESTQ CX, CX
	JZ    accum_done
	MOVQ  (SP), DX
	ADDQ  AX, DX
	MOVQ  DX, (SP)
	INCQ  AX
	DECQ  CX
	MOVQ  CX, 8(SP)
	JMP   accum_loop

accum_done:
	MOVQ (SP), AX
	MOVQ AX, ret+16(FP)
	RET

